import java.io.Serializable;

/**
 * POJO for a Google cluster-trace task_events row.
 *
 * Column order (clusterdata-2011-2):
 *   timestamp, missing_info, job_id, task_index, machine_id, event_type,
 *   user, scheduling_class, priority, cpu_request, memory_request,
 *   disk_space_request, different_machines_restriction
 *
 * Timestamps are in microseconds since trace start.
 */
public class TaskEvent implements Serializable {

    public long timestamp;
    public long jobId;
    public long taskIndex;
    public int eventType;

    public TaskEvent() {}

    public TaskEvent(long timestamp, long jobId, long taskIndex, int eventType) {
        this.timestamp = timestamp;
        this.jobId = jobId;
        this.taskIndex = taskIndex;
        this.eventType = eventType;
    }

    public static TaskEvent fromCsv(String line) {
        String[] f = line.split(",", -1);
        TaskEvent e = new TaskEvent();
        e.timestamp = Long.parseLong(f[0]);
        e.jobId = Long.parseLong(f[2]);
        e.taskIndex = f[3].isEmpty() ? -1L : Long.parseLong(f[3]);
        e.eventType = Integer.parseInt(f[5]);
        return e;
    }

    public long getEventTimeMillis() {
        return timestamp / 1000L;
    }

    @Override
    public String toString() {
        return "TaskEvent(" + timestamp + "," + jobId + "," + taskIndex + "," + eventType + ")";
    }
}
"}

